import { useThemeRevision } from '../../../shared/design/useThemeRevision';
import { themedStyles } from '../../../shared/design/themeRuntime';
import { useCivilToday } from '../../../core/clock/useCivilToday';
import { useMemo } from 'react';
import { ScrollView, StyleSheet, Text, View } from 'react-native';
import MaterialIcons from '@expo/vector-icons/MaterialIcons';

import { useAuth } from '../../auth/AuthProvider';
import { Money } from '../../../core/domain/money';
import { formatCurrency } from '../../../core/format/money';
import { formatTimestampDate } from '../../../core/format/date';
import { type CivilDate } from '../../../core/time/calendar';
import { borderWidth, colors, gaps, radius, sizes, spacing } from '../../../shared/design/tokens';
import { textStyle } from '../../../shared/design/typography';
import { AsyncStateView, type AsyncState } from '../../../shared/widgets/AsyncStateView';
import { ScreenTopBar } from '../../../shared/widgets/ScreenTopBar';
import { useSubscriptionsQuery } from '../../subscriptions/data/queries';
import { activeForTotals } from '../../subscriptions/domain/activeSelectors';
import { inCurrency } from '../../subscriptions/domain/currencyFilter';
import { useActiveCurrency, useUserTimeZone } from '../../settings/data/useActiveCurrency';
import { monthlyEquivalent, type Subscription } from '../../subscriptions/domain/subscription';
import { useSavingsQuery } from '../data/queries';
import { savingsEventTitle, topCostSentence, type SavingsEvent } from '../domain/savingsSummary';
import { SavingsRow } from './SavingsRow';

/**
 * Tasarruf analizi (Flutter `SavingsScreen`): her para birimi için en yüksek yıllık maliyetli üç abonelik,
 * tüm aktif aboneliklerin yıllık maliyeti ve duraklatma/iptal geçmişi. Dil tarafsızdır; iptal önerilmez.
 */
export function SavingsScreen() {
  useThemeRevision();
  const { user } = useAuth();
  const subscriptions = useSubscriptionsQuery(user?.id);
  const savings = useSavingsQuery(user?.id);
  const timeZone = useUserTimeZone();
  const today = useCivilToday(timeZone);

  const state: AsyncState<{ subscriptions: Subscription[]; savings: SavingsEvent[] }> =
    subscriptions.isPending || savings.isPending
      ? { status: 'loading' }
      : subscriptions.isError || savings.isError
        ? {
            status: 'error',
            message: 'Tasarruf verisi yüklenemedi. Bağlantını kontrol edip tekrar dene.',
            onRetry: () => {
              void subscriptions.refetch();
              void savings.refetch();
            },
          }
        : {
            status: 'ready',
            data: { subscriptions: subscriptions.data ?? [], savings: savings.data ?? [] },
          };

  return (
    <View style={styles.screen}>
      <ScreenTopBar title="Tasarruf analizi" />
      <AsyncStateView state={state}>
        {(data) => <SavingsBody subscriptions={data.subscriptions} events={data.savings} today={today} timeZone={timeZone} />}
      </AsyncStateView>
    </View>
  );
}

/** Bir para biriminde en yüksek aylık tutarlı en çok üç abonelik (Flutter `_Top3Card` girdisi). */
function topThree(active: readonly Subscription[]): Map<string, Subscription[]> {
  const byCurrency = new Map<string, Subscription[]>();
  for (const subscription of active) {
    byCurrency.set(subscription.currency, [...(byCurrency.get(subscription.currency) ?? []), subscription]);
  }
  for (const [currency, items] of byCurrency) {
    byCurrency.set(
      currency,
      [...items].sort((a, b) => monthlyEquivalent(b).minorUnits - monthlyEquivalent(a).minorUnits || a.name.localeCompare(b.name, 'tr-TR') || a.id.localeCompare(b.id)).slice(0, 3),
    );
  }
  return byCurrency;
}

/** Üst kart başlığı; birden çok para birimi varsa para birimi eklenir. */
function headline(showCurrency: boolean, currency: string): string {
  return showCurrency ? `En yüksek yıllık maliyetler · ${currency}` : 'En yüksek yıllık maliyetler';
}

/** Geçmiş satırı tarihi; geçersiz zaman damgasında `null` (tarih parçası yazılmaz). */
function eventDate(iso: string, timeZone: string): string | null {
  return Number.isNaN(new Date(iso).getTime()) ? null : formatTimestampDate(iso, timeZone);
}

function SavingsBody({ subscriptions, events, today, timeZone }: { subscriptions: Subscription[]; events: SavingsEvent[]; today: CivilDate; timeZone: string }) {
  useThemeRevision();
  // Tasarruf yalnızca aktif para birimini gösterir; diğer para birimlerinin olayları gizlenir.
  const currency = useActiveCurrency();
  const active = activeForTotals(inCurrency(subscriptions, currency), today);
  const visibleEvents = events.filter((event) => event.currency === currency);
  const groups = useMemo(() => topThree(active), [active]);
  const showCurrency = groups.size > 1;
  // Üst kartın saydığı üç kayıt "Tasarruf fırsatları"nda; geri kalanı "Diğer fırsatlar"da.
  const featuredIds = useMemo(() => new Set([...groups.values()].flat().map((item) => item.id)), [groups]);
  const featured = [...groups.values()].flat();
  const others = active.filter((item) => !featuredIds.has(item.id))
    .sort((a, b) => monthlyEquivalent(b).minorUnits - monthlyEquivalent(a).minorUnits);

  if (active.length === 0 && visibleEvents.length === 0) {
    return (
      <View style={styles.empty}>
        <Text style={textStyle('body', { color: colors.onSurfaceVariant, textAlign: 'center' })}>{`${currency} için aktif abonelik veya tasarruf geçmişi yok.`}</Text>
      </View>
    );
  }

  return (
    <ScrollView contentContainerStyle={styles.content} showsVerticalScrollIndicator={false}>
      {[...groups.entries()].map(([currency, items]) => {
        const monthly = items.reduce((sum: Money, item) => sum.add(monthlyEquivalent(item)), Money.zero);
        const yearly = monthly.multiply(12);
        return (
          <View key={currency} style={styles.topCard}>
            <Text style={textStyle('bodyStrong', { color: colors.onPrimaryContainer })}>{headline(showCurrency, currency)}</Text>
            <Text style={textStyle('heading', { color: colors.onPrimaryContainer, marginTop: spacing.sm })}>
              {`Tahmini: ${topCostSentence(items.length, formatCurrency(yearly, currency))}`}
            </Text>
            <Text style={textStyle('bodySmall', { color: colors.onPrimaryContainer })}>{`${formatCurrency(monthly, currency)}/ay`}</Text>
          </View>
        );
      })}

      {active.length > 0 ? <>
      <Text style={textStyle('bodyStrong', { marginTop: gaps.sectionInner - 2 })}>Tahmini yıllık maliyetler</Text>
      <Text style={textStyle('caption', { marginBottom: spacing.xs })}>Mevcut tutarlar üzerinden yıllık eşdeğerler, en yüksekten başlayarak.</Text>
      {featured.map((subscription) => (
        <SavingsRow key={subscription.id} subscription={subscription} />
      ))}
      {others.length > 0 ? (
        <>
          <Text style={textStyle('bodyStrong', { marginTop: gaps.rowLoose + spacing.xs - 2 })}>Diğer abonelikler</Text>
          {others.map((subscription) => (
            <SavingsRow key={subscription.id} subscription={subscription} />
          ))}
        </>
      ) : null}
      </> : <Text style={textStyle('bodySmall', { color: colors.onSurfaceVariant })}>{`${currency} için aktif abonelik yok.`}</Text>}

      {visibleEvents.length > 0 ? (
        <>
          <Text style={textStyle('bodyStrong', { marginTop: gaps.rowLoose + spacing.xs - 2 })}>İptal ve duraklatma geçmişi</Text>
          <Text style={textStyle('caption')}>Kaydedilen yıllık eşdeğer tutarlar; gerçekleşen tasarruf değildir.</Text>
          {visibleEvents.map((event, index) => (
            <View key={`${event.effectiveAt}-${index}`} style={styles.historyRow}>
              <MaterialIcons name="trending-down" size={sizes.iconButtonSize} color={colors.onSurfaceVariant} />
              <View style={styles.historyText}>
                <Text style={textStyle('body')}>{savingsEventTitle(event.eventType, eventDate(event.effectiveAt, timeZone))}</Text>
              </View>
              <Text style={textStyle('label')}>{`${formatCurrency(event.annual, event.currency)}/yıl`}</Text>
            </View>
          ))}
        </>
      ) : null}
      <View style={styles.bottom} />
    </ScrollView>
  );
}

const styles = themedStyles(() => StyleSheet.create({
  screen: {
    flex: 1,
    backgroundColor: colors.background,
  },
  content: {
    padding: spacing.lg,
  },
  empty: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
    padding: spacing.xl,
  },
  topCard: {
    padding: spacing.lg,
    marginBottom: spacing.md,
    borderRadius: radius.medium,
    borderWidth: borderWidth.hairline,
    borderColor: colors.outlineHalf,
    backgroundColor: colors.primaryContainer,
  },
  historyRow: {
    flexDirection: 'row',
    alignItems: 'center',
    marginTop: spacing.xs,
    paddingHorizontal: gaps.cardInset,
    paddingVertical: spacing.sm,
    borderRadius: radius.medium,
    borderWidth: borderWidth.hairline,
    borderColor: colors.outlineHalf,
    backgroundColor: colors.surface,
  },
  historyText: {
    flex: 1,
    marginLeft: spacing.md,
  },
  bottom: {
    height: sizes.bottomNavHeight,
  },
}));
